extends Node
## Keyboard -> logic. Polls actions with is_action_just_pressed, so a held key or OS
## key-repeat echo can never fire an action twice. Movement (camera-relative) is read
## by the presentation through move_vector(); everything else goes straight to the logic.

const InputSetup = preload("res://logic/input_setup.gd")

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	InputSetup.ensure_actions()

func _process(_delta: float) -> void:
	var ls: Node = get_node("/root/LoopState")
	var story: Node = get_node("/root/Story")
	var sound: Node = get_node("/root/SoundBank")
	if Input.is_action_just_pressed("quit") and ls.is_ended():
		get_tree().quit()
		return
	if Input.is_action_just_pressed("pause") and not ls.is_ended():
		ls.set_paused(not get_tree().paused)
	if Input.is_action_just_pressed("mute_music"):
		sound.toggle_bus_mute("Music")
	if Input.is_action_just_pressed("mute_sfx"):
		sound.toggle_bus_mute("SFX")
	if get_tree().paused:
		return
	ls.fast_forward = Input.is_action_pressed("fast_forward")
	if ls.is_ended() and Input.is_action_just_pressed("restart"):
		ls.begin_slice()
		return
	if Input.is_action_just_pressed("choice_up"):
		story.move_choice(-1)
	if Input.is_action_just_pressed("choice_down"):
		story.move_choice(1)
	if Input.is_action_just_pressed("interact"):
		story.press_interact()

## WASD / arrows as a 2D vector (x = right, y = down/back), for camera-relative movement.
func move_vector() -> Vector2:
	return Input.get_vector("move_left", "move_right", "move_up", "move_down")

extends MeshInstance3D
## A floor/water/backdrop surface: uses art_path if present, else a fallback.
## Fallback is a generated placeholder image (placeholder_kind) or a plain colour.

const Art3D = preload("res://scenes/art3d.gd")

@export var art_path := ""
@export var placeholder_kind := ""       ## "" = plain fallback_color
@export var fallback_color := Color.WHITE
@export var uv_tiles := Vector2.ONE      ## texture repeats (marble tiles)
@export var unshaded := false            ## backdrops: unshaded, tinted by the clock instead
@export var transparent := false
@export var emission := 0.0
@export var draw_after := 0              ## render_priority: overlays draw over the backdrop behind them
var material: StandardMaterial3D
var has_art := false

func _ready() -> void:
	var tex := Art3D.load_texture(art_path)
	has_art = tex != null
	if not has_art and placeholder_kind != "":
		tex = ImageTexture.create_from_image(Art3D.placeholder(placeholder_kind))
	material = StandardMaterial3D.new()
	material.albedo_color = Color.WHITE if tex else fallback_color
	material.albedo_texture = tex
	material.uv1_scale = Vector3(uv_tiles.x, uv_tiles.y, 1)
	if unshaded:
		material.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	if transparent:
		material.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
		material.cull_mode = BaseMaterial3D.CULL_DISABLED
	if emission > 0.0:
		material.emission_enabled = true
		material.emission = fallback_color
		material.emission_energy_multiplier = emission
		if tex:
			material.emission_texture = tex
	material.render_priority = draw_after
	material_override = material

## Clock tint for unshaded backdrops; alpha for overlays that fade in.
func set_tint(color: Color) -> void:
	if material:
		material.albedo_color = color
